public abstract class Sanitizer {
    private static final String SPECIAL_CHARACTERS_PATTERN = "([#;'\\\\])";
    private static final String ESCAPED = "\\\\$1";

    @SuppressWarnings("unchecked")
    public static <T> T sanitize(T value) {
        if (value instanceof String) {
            var result = (String) value;
            result = result.replaceAll(SPECIAL_CHARACTERS_PATTERN, ESCAPED);
            return (T) result;
        }
        return value;
    }
}


